import React, { useState, useEffect, useRef, useCallback } from "react";
import { Check, X, RotateCcw, Clock, Trophy } from "lucide-react";

const CURSIVE_FONT_B64 = "";

const LETTERS = [
  { char: "א", name: "ALEF", group: null },
  { char: "ב", name: "BET", group: "bet-kaf" },
  { char: "ג", name: "GIMEL", group: "gimel-nun" },
  { char: "ד", name: "DALET", group: "dalet-resh" },
  { char: "ה", name: "HE", group: "he-het-tav" },
  { char: "ו", name: "VAV", group: "vav-zayin-yod" },
  { char: "ז", name: "ZAYIN", group: "vav-zayin-yod" },
  { char: "ח", name: "HET", group: "he-het-tav" },
  { char: "ט", name: "TET", group: null },
  { char: "י", name: "YOD", group: "vav-zayin-yod" },
  { char: "כ", name: "KAF", group: "bet-kaf" },
  { char: "ל", name: "LAMED", group: null },
  { char: "מ", name: "MEM", group: null },
  { char: "נ", name: "NUN", group: "gimel-nun" },
  { char: "ס", name: "SAMEKH", group: null },
  { char: "ע", name: "AYIN", group: "ayin-tsadi" },
  { char: "פ", name: "PE", group: null },
  { char: "צ", name: "TSADI", group: "ayin-tsadi" },
  { char: "ק", name: "KOF", group: null },
  { char: "ר", name: "RESH", group: "dalet-resh" },
  { char: "ש", name: "SHIN", group: null },
  { char: "ת", name: "TAV", group: "he-het-tav" },
];

const MODES = [
  { id: "print", label: "Lecture" },
  { id: "cursive", label: "Cursive" },
  { id: "traps", label: "Pieges" },
];

const MASTERY_TARGET = 3;
const ROUND_LENGTH = 20;
const STORAGE_KEY = "hebrew-drill-progress-v1";

function shuffle(arr) {
  const a = [...arr];
  for (let i = a.length - 1; i > 0; i--) {
    const j = Math.floor(Math.random() * (i + 1));
    [a[i], a[j]] = [a[j], a[i]];
  }
  return a;
}

function pickWeighted(pool, progress) {
  const weights = pool.map((l) => {
    const p = progress[l.char] || { streak: 0 };
    return Math.max(1, MASTERY_TARGET + 2 - p.streak);
  });
  const total = weights.reduce((a, b) => a + b, 0);
  let r = Math.random() * total;
  for (let i = 0; i < pool.length; i++) {
    r -= weights[i];
    if (r <= 0) return pool[i];
  }
  return pool[pool.length - 1];
}

function makeQuestion(mode, progress) {
  const pool = mode === "traps" ? LETTERS.filter((l) => l.group) : LETTERS;
  const target = pickWeighted(pool, progress);

  let distractorPool = LETTERS.filter((l) => l.char !== target.char);
  if (target.group) {
    const sameGroup = distractorPool.filter((l) => l.group === target.group);
    distractorPool = shuffle([
      ...sameGroup,
      ...shuffle(distractorPool.filter((l) => l.group !== target.group)),
    ]);
  } else {
    distractorPool = shuffle(distractorPool);
  }
  const distractors = distractorPool.slice(0, 3);
  const options = shuffle([target, ...distractors]);
  return { target, options };
}

function formatTime(sec) {
  const h = Math.floor(sec / 3600);
  const m = Math.floor((sec % 3600) / 60);
  const s = sec % 60;
  return (h > 0 ? h + ":" : "") + String(m).padStart(2, "0") + ":" + String(s).padStart(2, "0");
}

function startRound(mode, progress) {
  return {
    question: makeQuestion(mode, progress),
    qNum: 1,
    score: 0,
    missed: [],
    over: false,
  };
}

export default function App() {
  const [mode, setMode] = useState("print");
  const [progress, setProgress] = useState({});
  const [round, setRound] = useState(() => startRound("print", {}));
  const [selected, setSelected] = useState(null);
  const [feedback, setFeedback] = useState(null);
  const [elapsed, setElapsed] = useState(0);
  const [loaded, setLoaded] = useState(false);
  const advanceTimer = useRef(null);

  useEffect(() => {
    let mounted = true;
    (async () => {
      try {
        const res = await window.storage?.get(STORAGE_KEY, false);
        if (mounted && res?.value) {
          setProgress(JSON.parse(res.value));
        }
      } catch (e) {}
      finally {
        if (mounted) setLoaded(true);
      }
    })();
    return () => {
      mounted = false;
    };
  }, []);

  useEffect(() => {
    if (!loaded) return;
    window.storage?.set(STORAGE_KEY, JSON.stringify(progress), false).catch(() => {});
  }, [progress, loaded]);

  useEffect(() => {
    const id = setInterval(() => setElapsed((e) => e + 1), 1000);
    return () => clearInterval(id);
  }, []);

  useEffect(() => {
    setRound(startRound(mode, progress));
    setSelected(null);
    setFeedback(null);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [mode]);

  const modeProgress = LETTERS.filter((l) => (mode === "traps" ? l.group : true));
  const masteredCount = modeProgress.filter(
    (l) => (progress[l.char]?.streak || 0) >= MASTERY_TARGET
  ).length;

  const handleAnswer = useCallback(
    (opt) => {
      if (feedback || round.over) return;
      const correct = opt.char === round.question.target.char;
      setSelected(opt.char);
      setFeedback(correct ? "correct" : "wrong");

      const targetChar = round.question.target.char;
      const targetName = round.question.target.name;

      setProgress((prev) => {
        const cur = prev[targetChar] || { streak: 0, seen: 0, wrong: 0 };
        return {
          ...prev,
          [targetChar]: {
            streak: correct ? cur.streak + 1 : 0,
            seen: cur.seen + 1,
            wrong: cur.wrong + (correct ? 0 : 1),
          },
        };
      });

      advanceTimer.current = setTimeout(
        () => {
          setRound((prevRound) => {
            const newScore = prevRound.score + (correct ? 1 : 0);
            const newMissed = correct
              ? prevRound.missed
              : [...prevRound.missed, targetName];
            if (prevRound.qNum >= ROUND_LENGTH) {
              return { ...prevRound, score: newScore, missed: newMissed, over: true };
            }
            return {
              question: makeQuestion(mode, progress),
              qNum: prevRound.qNum + 1,
              score: newScore,
              missed: newMissed,
              over: false,
            };
          });
          setSelected(null);
          setFeedback(null);
        },
        correct ? 550 : 1400
      );
    },
    [feedback, round, mode, progress]
  );

  useEffect(() => () => clearTimeout(advanceTimer.current), []);

  const resetProgress = () => {
    setProgress({});
    window.storage?.set(STORAGE_KEY, JSON.stringify({}), false).catch(() => {});
  };

  const restartRound = () => {
    setRound(startRound(mode, progress));
    setSelected(null);
    setFeedback(null);
  };

  const isCursive = mode === "cursive";
  const pct = Math.round((round.score / ROUND_LENGTH) * 100);
  const uniqueMissed = [...new Set(round.missed)];

  return (
    <div style={styles.page}>
      <style>{`
        @font-face {
          font-family: 'GveretLevin';
          src: url(data:font/ttf;base64,${CURSIVE_FONT_B64}) format('truetype');
          font-display: swap;
        }
        * { box-sizing: border-box; }
        body { margin: 0; }
        .opt-btn { transition: transform 120ms ease, background 120ms ease, border-color 120ms ease; }
        .opt-btn:active { transform: scale(0.97); }
        .restart-btn:active { transform: scale(0.97); }
        @keyframes pop { 0% { transform: scale(0.85); opacity: 0; } 100% { transform: scale(1); opacity: 1; } }
        @keyframes fadeUp { 0% { opacity: 0; transform: translateY(8px); } 100% { opacity: 1; transform: translateY(0); } }
        .letter-pop { animation: pop 220ms ease; }
        .results-in { animation: fadeUp 260ms ease; }
      `}</style>

      <div style={styles.header}>
        <div style={styles.headerLeft}>
          <div style={styles.title}>Alphabet Hebreu</div>
          <div style={styles.subtitle}>22 lettres de base</div>
        </div>
        <div style={styles.timer}>
          <Clock size={14} style={{ opacity: 0.6 }} />
          {formatTime(elapsed)}
        </div>
      </div>

      <div style={styles.tabs}>
        {MODES.map((m) => (
          <button
            key={m.id}
            onClick={() => setMode(m.id)}
            style={{
              ...styles.tab,
              ...(mode === m.id ? styles.tabActive : {}),
            }}
          >
            {m.label}
          </button>
        ))}
      </div>

      <div style={styles.progressRow}>
        <div style={styles.progressBarTrack}>
          <div
            style={{
              ...styles.progressBarFill,
              width: `${(masteredCount / modeProgress.length) * 100}%`,
            }}
          />
        </div>
        <div style={styles.progressLabel}>
          {masteredCount}/{modeProgress.length} maitrisees
        </div>
      </div>

      {!round.over && (
        <div style={styles.roundRow}>
          <span>Question {round.qNum}/{ROUND_LENGTH}</span>
          <span style={styles.scoreTag}>Score {round.score}</span>
        </div>
      )}

      {!round.over ? (
        <div style={styles.card}>
          <div
            key={round.question.target.char + mode + round.qNum}
            className="letter-pop"
            style={{
              ...styles.bigLetter,
              fontFamily: isCursive ? "GveretLevin, sans-serif" : "'Noto Sans Hebrew', 'Arial Hebrew', sans-serif",
            }}
          >
            {round.question.target.char}
          </div>

          <div style={styles.optionsGrid}>
            {round.question.options.map((opt) => {
              const isSelected = selected === opt.char;
              const isCorrectOpt = opt.char === round.question.target.char;
              let bg = "#1f1f23";
              let border = "#2c2c31";
              let color = "#f5f5f5";
              if (feedback && isCorrectOpt) {
                bg = "rgba(74, 222, 128, 0.15)";
                border = "#4ade80";
                color = "#4ade80";
              } else if (feedback && isSelected && !isCorrectOpt) {
                bg = "rgba(255, 107, 107, 0.15)";
                border = "#ff6b6b";
                color = "#ff6b6b";
              }
              return (
                <button
                  key={opt.char}
                  className="opt-btn"
                  onClick={() => handleAnswer(opt)}
                  disabled={!!feedback}
                  style={{ ...styles.optionBtn, background: bg, borderColor: border, color }}
                >
                  <span>{opt.name}</span>
                  {feedback && isCorrectOpt && <Check size={18} />}
                  {feedback && isSelected && !isCorrectOpt && <X size={18} />}
                </button>
              );
            })}
          </div>
        </div>
      ) : (
        <div style={styles.card} className="results-in">
          <Trophy size={34} style={{ color: "#ff6b6b", marginBottom: 14 }} />
          <div style={styles.resultScore}>{round.score}/{ROUND_LENGTH}</div>
          <div style={styles.resultPct}>{pct}% de bonnes reponses</div>

          {uniqueMissed.length > 0 ? (
            <div style={styles.missedBox}>
              <div style={styles.missedTitle}>A revoir</div>
              <div style={styles.missedList}>{uniqueMissed.join(" · ")}</div>
            </div>
          ) : (
            <div style={styles.missedBox}>
              <div style={styles.missedTitle}>Sans faute</div>
            </div>
          )}

          <button className="restart-btn" onClick={restartRound} style={styles.restartBtn}>
            <RotateCcw size={16} /> Recommencer
          </button>
        </div>
      )}

      <div style={styles.footer}>
        <div style={styles.miniGrid}>
          {LETTERS.map((l) => {
            const streak = progress[l.char]?.streak || 0;
            const done = streak >= MASTERY_TARGET;
            return (
              <div
                key={l.char}
                title={l.name}
                style={{
                  ...styles.miniDot,
                  background: done ? "#4ade80" : streak > 0 ? "#ff6b6b55" : "#2c2c31",
                }}
              />
            );
          })}
        </div>
        <button onClick={resetProgress} style={styles.resetBtn}>
          <RotateCcw size={13} /> reinitialiser la maitrise
        </button>
      </div>
    </div>
  );
}

